  1→"use client";
  2→
  3→/**
  4→ * Main chat interface for the thos dashboard.
  5→ *
  6→ * Composes {@link StatusBar}, a scrollable message list ({@link Message}
  7→ * and {@link ControlRequest} cards), and an input bar. The submit button
  8→ * text toggles between "Spawn" (when idle/done) and "Send" (when an
  9→ * agent session is active). Auto-scrolls on new messages.
 10→ *
 11→ * Receives all data and callbacks via props — the parent page component
 12→ * owns the WebSocket hook and orchestrates multiple agents.
 13→ */
 14→
 15→import { useEffect, useRef, useState } from "react";
 16→import type { AgentStatus, ChatMessage } from "@/lib/types";
 17→import { StatusBar } from "./status-bar";
 18→import { Message } from "./message";
 19→import { ControlRequest } from "./control-request";
 20→import { Button } from "@/components/ui/button";
 21→
 22→export function Chat({
 23→  connected,
 24→  status,
 25→  messages,
 26→  onSendMessage,
 27→  onSpawnAgent,
 28→  onRespondToControl,
 29→}: {
 30→  connected: boolean;
 31→  status: AgentStatus;
 32→  messages: ChatMessage[];
 33→  onSendMessage: (content: string) => void;
 34→  onSpawnAgent: (prompt: string) => void;
 35→  onRespondToControl: (requestId: string, allow: boolean) => void;
 36→}) {
 37→  const [input, setInput] = useState("");
 38→  const scrollRef = useRef<HTMLDivElement>(null);
 39→
 40→  useEffect(() => {
 41→    scrollRef.current?.scrollTo({
 42→      top: scrollRef.current.scrollHeight,
 43→      behavior: "smooth",
 44→    });
 45→  }, [messages]);
 46→
 47→  const isActive = status === "connected" || status === "thinking";
 48→
 49→  function handleSubmit(e: React.FormEvent) {
 50→    e.preventDefault();
 51→    const trimmed = input.trim();
 52→    if (!trimmed) return;
 53→
 54→    if (isActive) {
 55→      onSendMessage(trimmed);
 56→    } else {
 57→      onSpawnAgent(trimmed);
 58→    }
 59→    setInput("");
 60→  }
 61→
 62→  return (
 63→    <div className="flex h-full flex-col">
 64→      <StatusBar connected={connected} status={status} />
 65→
 66→      <div ref={scrollRef} className="flex-1 overflow-y-auto p-4 space-y-2">
 67→        {messages.length === 0 && (
 68→          <div className="flex h-full items-center justify-center text-sm text-muted-foreground">
 69→            Type a prompt to spawn a Claude agent
 70→          </div>
 71→        )}
 72→        {messages.map((msg) =>
 73→          msg.controlRequest ? (
 74→            <ControlRequest
 75→              key={msg.id}
 76→              message={msg}
 77→              onRespond={onRespondToControl}
 78→            />
 79→          ) : (
 80→            <Message key={msg.id} message={msg} />
 81→          )
 82→        )}
 83→      </div>
 84→
 85→      <form
 86→        onSubmit={handleSubmit}
 87→        className="flex gap-2 border-t px-4 py-3"
 88→      >
 89→        <input
 90→          type="text"
 91→          value={input}
 92→          onChange={(e) => setInput(e.target.value)}
 93→          placeholder={isActive ? "Send a follow-up..." : "Enter a prompt to spawn agent..."}
 94→          className="flex-1 rounded-md border bg-background px-3 py-2 text-sm outline-none focus:ring-2 focus:ring-ring"
 95→        />
 96→        <Button type="submit" disabled={!connected || !input.trim()}>
 97→          {isActive ? "Send" : "Spawn"}
 98→        </Button>
 99→      </form>
100→    </div>
101→  );
102→}
103→

 1→"use client";
 2→
 3→/**
 4→ * Single chat message bubble.
 5→ * - **user** — right-aligned, primary background.
 6→ * - **assistant** — left-aligned, secondary background.
 7→ * - **system** — centered, italic, muted (used for init info, result summaries, errors).
 8→ */
 9→
10→import type { ChatMessage } from "@/lib/types";
11→import { cn } from "@/lib/utils";
12→
13→export function Message({ message }: { message: ChatMessage }) {
14→  if (message.role === "system") {
15→    return (
16→      <div className="py-1 text-center text-xs italic text-muted-foreground">
17→        {message.content}
18→      </div>
19→    );
20→  }
21→
22→  const isUser = message.role === "user";
23→
24→  return (
25→    <div className={cn("flex", isUser ? "justify-end" : "justify-start")}>
26→      <div
27→        className={cn(
28→          "max-w-[80%] rounded-lg px-3 py-2 text-sm whitespace-pre-wrap",
29→          isUser
30→            ? "bg-primary text-primary-foreground"
31→            : "bg-secondary text-secondary-foreground"
32→        )}
33→      >
34→        {message.content}
35→      </div>
36→    </div>
37→  );
38→}
