  1→/**
  2→ * File-based session persistence for thos agents.
  3→ *
  4→ * Persists agent state + message history to JSON files in
  5→ * `$TMPDIR/thos-sessions/<agentId>.json` so data survives server restarts.
  6→ *
  7→ * Uses debounced writes (150ms) for high-frequency events (streaming) and
  8→ * synchronous writes for critical state changes (spawn, result, status).
  9→ */
 10→
 11→import { mkdirSync, writeFileSync, readFileSync, readdirSync, unlinkSync, existsSync } from "fs";
 12→import { join } from "path";
 13→import { tmpdir } from "os";
 14→import type { AgentStatus, ServerMessage } from "../lib/types";
 15→
 16→const SESSION_DIR = join(tmpdir(), "thos-sessions");
 17→
 18→/** Shape of a persisted agent on disk. */
 19→export interface PersistedAgent {
 20→  id: string;
 21→  state: {
 22→    agentId: string;
 23→    status: AgentStatus;
 24→    tmuxSession: string | null;
 25→    label: string;
 26→    createdAt: number;
 27→    sessionId: string | null;
 28→  };
 29→  messageHistory: ServerMessage[];
 30→}
 31→
 32→export class SessionStore {
 33→  private dir: string;
 34→  private debounceTimers = new Map<string, ReturnType<typeof setTimeout>>();
 35→
 36→  constructor(dir: string = SESSION_DIR) {
 37→    this.dir = dir;
 38→    mkdirSync(this.dir, { recursive: true });
 39→  }
 40→
 41→  /** File path for a given agent ID. */
 42→  private filePath(agentId: string): string {
 43→    return join(this.dir, `${agentId}.json`);
 44→  }
 45→
 46→  /** Debounced write — batches rapid stream events (150ms). */
 47→  save(agent: PersistedAgent): void {
 48→    const existing = this.debounceTimers.get(agent.id);
 49→    if (existing) clearTimeout(existing);
 50→    this.debounceTimers.set(
 51→      agent.id,
 52→      setTimeout(() => {
 53→        this.debounceTimers.delete(agent.id);
 54→        this.writeFile(agent);
 55→      }, 150)
 56→    );
 57→  }
 58→
 59→  /** Immediate write — use for critical state changes (spawn, result, status). */
 60→  saveSync(agent: PersistedAgent): void {
 61→    // Cancel any pending debounced write
 62→    const existing = this.debounceTimers.get(agent.id);
 63→    if (existing) {
 64→      clearTimeout(existing);
 65→      this.debounceTimers.delete(agent.id);
 66→    }
 67→    this.writeFile(agent);
 68→  }
 69→
 70→  /** Load a single agent from disk. Returns null if not found. */
 71→  load(agentId: string): PersistedAgent | null {
 72→    const fp = this.filePath(agentId);
 73→    if (!existsSync(fp)) return null;
 74→    try {
 75→      const raw = readFileSync(fp, "utf-8");
 76→      return JSON.parse(raw) as PersistedAgent;
 77→    } catch (err) {
 78→      console.error(`[session-store] failed to load ${agentId}:`, err);
 79→      return null;
 80→    }
 81→  }
 82→
 83→  /** Load all persisted agents on server startup. */
 84→  loadAll(): PersistedAgent[] {
 85→    try {
 86→      const files = readdirSync(this.dir).filter((f) => f.endsWith(".json"));
 87→      const agents: PersistedAgent[] = [];
 88→      for (const file of files) {
 89→        try {
 90→          const raw = readFileSync(join(this.dir, file), "utf-8");
 91→          agents.push(JSON.parse(raw) as PersistedAgent);
 92→        } catch (err) {
 93→          console.error(`[session-store] failed to parse ${file}:`, err);
 94→        }
 95→      }
 96→      return agents;
 97→    } catch {
 98→      return [];
 99→    }
100→  }
101→
102→  /** Delete an agent's persisted file. */
103→  remove(agentId: string): void {
104→    const fp = this.filePath(agentId);
105→    try {
106→      if (existsSync(fp)) unlinkSync(fp);
107→    } catch (err) {
108→      console.error(`[session-store] failed to remove ${agentId}:`, err);
109→    }
110→    // Also cancel any pending debounced write
111→    const existing = this.debounceTimers.get(agentId);
112→    if (existing) {
113→      clearTimeout(existing);
114→      this.debounceTimers.delete(agentId);
115→    }
116→  }
117→
118→  /** Flush all pending debounced writes synchronously (for graceful shutdown). */
119→  flushAll(allAgents: PersistedAgent[]): void {
120→    // Cancel all pending timers
121→    for (const [id, timer] of this.debounceTimers) {
122→      clearTimeout(timer);
123→      this.debounceTimers.delete(id);
124→    }
125→    // Write all agents
126→    for (const agent of allAgents) {
127→      this.writeFile(agent);
128→    }
129→  }
130→
131→  private writeFile(agent: PersistedAgent): void {
132→    try {
133→      writeFileSync(this.filePath(agent.id), JSON.stringify(agent, null, 2));
134→    } catch (err) {
135→      console.error(`[session-store] failed to write ${agent.id}:`, err);
136→    }
137→  }
138→}
