142→function getInitialSessionNames(): Map<string, string> {
143→  if (typeof window === "undefined") return new Map();
144→  try {
145→    return new Map(JSON.parse(localStorage.getItem("cc-session-names") || "[]"));
146→  } catch {
147→    return new Map();
148→  }
149→}
150→
151→function getInitialSessionId(): string | null {
152→  if (typeof window === "undefined") return null;
153→  return localStorage.getItem("cc-current-session") || null;
154→}
155→
156→function getInitialDarkMode(): boolean {
157→  if (typeof window === "undefined") return false;
158→  const stored = localStorage.getItem("cc-dark-mode");
159→  if (stored !== null) return stored === "true";
160→  return window.matchMedia("(prefers-color-scheme: dark)").matches;
161→}
162→
163→function getInitialNotificationSound(): boolean {
164→  if (typeof window === "undefined") return true;
165→  const stored = localStorage.getItem("cc-notification-sound");
166→  if (stored !== null) return stored === "true";
167→  return true;
168→}
169→
170→function getInitialDismissedVersion(): string | null {
171→  if (typeof window === "undefined") return null;
172→  return localStorage.getItem("cc-update-dismissed") || null;
173→}
174→
175→function getInitialCollapsedProjects(): Set<string> {
176→  if (typeof window === "undefined") return new Set();
177→  try {
178→    return new Set(JSON.parse(localStorage.getItem("cc-collapsed-projects") || "[]"));
179→  } catch {
180→    return new Set();
181→  }
182→}
